import React,{useState,useRef,useEffect} from 'react';
import {Upload,FileText,Plus,ArrowRight,ArrowUpRight,Check,CheckCheck,Search,Send,ShieldCheck,LockKeyhole,RefreshCw,Download,ExternalLink,Copy,ChevronRight,Globe,Mail,MessageCircle,Activity,Clock,BookOpen,Layers,SlidersHorizontal,Target,ArrowLeft,BriefcaseBusiness,AlertTriangle,Settings2,LogOut,Wallet,Receipt,Users,CalendarDays,X} from 'lucide-react';
import {Button,Tag,Avatar,Panel,Empty,Field,Modal,Notice,SectionTitle,fmt,money,Status,Source,names} from './ui';
import {parseFile} from './api';
const catchIt=p=>p?.catch(()=>{});
const rows=(s,k)=>s.data?.[k]||[];
const hasAll=f=>f.length>0;
const DEFAULT_ANSWERS={market:'马来西亚',products:'',buyers:['经销商','工程承包商'],inquiries:20,deals:'',channels:['WhatsApp','Facebook 主页'],time:'15 分钟',horizon:'3 个月'};
const ANSWERS_KEY='tradecrew.strategy.answers';
const loadAnswers=()=>{try{return {...DEFAULT_ANSWERS,...JSON.parse(localStorage.getItem(ANSWERS_KEY)||'{}')}}catch{return {...DEFAULT_ANSWERS}}};
const saveAnswers=a=>{try{localStorage.setItem(ANSWERS_KEY,JSON.stringify(a))}catch{}};
export function Knowledge({state,go,mutate,notify,busy,guard}){
 const [tab,setTab]=useState('facts'),[modal,setModal]=useState(null),[excluded,setExcluded]=useState([]),[query,setQuery]=useState(''),[uploading,setUploading]=useState(false);
 const facts=rows(state,'fact'),documents=rows(state,'document'),pending=facts.filter(f=>f.data.status==='pending'),confirmed=facts.filter(f=>f.data.status==='confirmed');
 const pendingIds=pending.map(f=>f.id),selected=pendingIds.filter(id=>!excluded.includes(id));
 useEffect(()=>{setExcluded(e=>e.filter(id=>pendingIds.includes(id)))},[pendingIds.join(',')]);
 const confirmFacts=async ids=>{const out=await mutate('/facts/confirm',{ids,resolve_conflicts:true,strategy_answers:loadAnswers()});setExcluded([]);
  if(out?.auto_strategy){notify('事实已确认，总管已自动开始制定出海方案');go('strategy');return;}
  notify('已确认的事实，现在可供团队使用');
  const strategies=rows(state,'strategy'),jobs=state.jobs.filter(j=>j.kind==='strategy');
  if(!strategies.length&&!jobs.some(j=>['pending','running'].includes(j.status))){
   const blocked=jobs.find(j=>j.status==='blocked');
   if(blocked){await mutate('/jobs/retry',{id:blocked.id},'总管正在重新制定出海方案');go('strategy');}
  }};
 const upload=async files=>{if(!guard())return;setUploading(true);try{for(const f of files)await mutate('/documents',await parseFile(f));notify('资料已接收，文员正在处理')}catch(e){notify(e.message,true)}finally{setUploading(false)}};
 return <><SectionTitle title="把工厂资料，变成团队的共同事实" description="先整理，再确认。每条对外表达都能回到一份原始资料。"><Button variant="outline" icon={Plus} onClick={()=>guard(()=>setModal('add'))}>补充事实</Button><label className="btn"><Upload size={16}/>{uploading?'正在读取…':'上传资料'}<input type="file" hidden accept=".pdf,.docx,.xlsx,.xls,.csv,.txt,.md" onChange={e=>upload(e.target.files)}/></label></SectionTitle><div className="stats-strip"><div><span>已确认事实</span><strong>{confirmed.length}<small>条</small></strong></div><div><span>待你确认</span><strong className="amber-text">{pending.length}<small>条</small></strong></div><div><span>原始资料</span><strong>{documents.length}<small>份</small></strong></div><div className="stats-action"><ShieldCheck size={27}/><p>只有你确认过的内容<br/>才是团队可以对外说的事实</p></div></div><div className="tabs-line">{[['facts','事实库'],['documents','原始资料'],['gaps','资料缺口'],['prices','价格参数']].map(([id,label])=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}>{label}{id==='facts'&&pending.length?<Tag tone="amber">{pending.length}</Tag>:null}</button>)}<div className="tabs-spacer"/><label className="search"><Search size={16}/><input placeholder="搜索字段或内容" value={query} onChange={e=>setQuery(e.target.value)}/></label></div>{tab==='facts'?<Panel className="table-panel">{pending.length?<div className="table-toolbar"><span><Tag tone="amber">关口 ①</Tag> 文员整理出 {pending.length} 条事实草稿，默认全部认可。有异议请取消勾选或单条修改，也可以在团队里告诉总管。</span><Button variant="small" disabled={!selected.length} loading={busy} icon={Check} onClick={()=>catchIt(confirmFacts(selected))}>确认 {selected.length} 条事实</Button></div>:null}{facts.length?<div className="table-wrap"><table><thead><tr><th></th><th>事实字段</th><th>事实内容</th><th>原文与来源</th><th>状态</th><th></th></tr></thead><tbody>{facts.filter(f=>JSON.stringify(f.data).toLowerCase().includes(query.toLowerCase())).map(f=><tr key={f.id} className={f.data.status==='superseded'?'muted-row':''}><td>{f.data.status==='pending'?<input aria-label={'选择'+f.data.field} type="checkbox" checked={!excluded.includes(f.id)} onChange={e=>setExcluded(x=>e.target.checked?x.filter(id=>id!==f.id):[...x,f.id])}/>:<CheckCheck size={15}/>}</td><td><strong>{f.data.field}</strong>{f.data.conflict?<Tag tone="red">来源冲突</Tag>:null}</td><td className="fact-value">{f.data.value}</td><td><span className="source-name">{f.data.source_name}</span><small className="evidence">“{f.data.evidence}”</small></td><td><Status status={f.data.status}/></td><td>{f.data.status==='pending'?<button className="text-link" onClick={()=>setModal({type:'confirm',fact:f})}>核对 <ChevronRight size={13}/></button>:<small>v{f.data.version||1}</small>}</td></tr>)}</tbody></table></div>:<Empty icon={FileText} title="团队还不了解你的产品" description="上传目录、报价单或粘贴官网文字。文员会整理有原文依据的事实草稿，不会自行补全。"><Button icon={ArrowRight} onClick={()=>go('today')}>开始建立事实库</Button></Empty>}</Panel>:tab==='documents'?<Panel>{documents.length?documents.map(d=><div className="document-row" key={d.id}><span className="file-icon"><FileText size={22}/></span><div><strong>{d.data.name}</strong><small>{fmt(d.created_at)} · {d.data.text.length.toLocaleString()} 字</small></div><Status status={d.data.parsed?'done':'pending'}/>{d.data.storage_key?<a className="icon-btn" aria-label="下载资料" href={'/api/file?id='+d.id}><Download size={17}/></a>:null}<button className="text-link" onClick={()=>setModal({type:'document',document:d})}>查看原文</button></div>):<Empty title="原始资料会保存在这里" description="与事实条目关联，可随时追溯。"/>}</Panel>:tab==='gaps'?<Panel><SectionTitle title="只追问真正缺少的资料" description="这些内容暂时不能向买家承诺，补充后仍需你确认。"/>{documents.flatMap(d=>(d.data.gaps||[]).map((g,i)=><div key={d.id+i} className="gap-row"><span className="amber-dot"/><div><strong>{g}</strong><small>文员 · 来自 {d.data.name}</small></div><Button variant="outline small" onClick={()=>setModal('add')}>补充说明</Button></div>))}{!documents.some(d=>d.data.gaps?.length)?<Empty icon={ShieldCheck} title="还没有待补充的缺口" description="文员完成资料整理后，会把需要你回答的问题放在这里。"/>:null}</Panel>:<PriceSettings {...{state,mutate,busy,guard,notify}}/>}{hasAll(confirmed)?<div className="next-step"><span><CheckCheck size={18}/>事实已确认，总管将据此自动制定出海方案。</span><Button onClick={()=>go('strategy')} icon={ArrowRight}>查看出海方案</Button></div>:null}{modal==='add'?<Modal title="补充一条真实的产品事实" description="这条说明会保留为原始来源，保存后还需在事实库确认。" onClose={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();try{await mutate('/facts/add',Object.fromEntries(new FormData(e.currentTarget)),'已加入待确认事实');setModal(null)}catch{}}}><Field label="事实字段"><input name="field" placeholder="例如：材质证明、保修期限、交期" required/></Field><Field label="事实内容"><textarea name="value" placeholder="请写明真实规格或条款；不确定的内容不要填。" required/></Field><Button type="submit" loading={busy}>保存待确认事实</Button></form></Modal>:modal?.type==='confirm'?<Modal title="核对原文，确认事实" onClose={()=>setModal(null)}><div className="review-content"><Tag tone="amber">关口 ① · 产品事实</Tag><h3>{modal.fact.data.field}</h3><p>{modal.fact.data.value}</p><blockquote>{modal.fact.data.evidence}</blockquote><small>来源：{modal.fact.data.source_name}</small>{modal.fact.data.conflict?<Notice tone="warning">该字段与现有事实不同。确认此版本后，旧的已确认版本将转为历史版本，记录仍保留。</Notice>:null}<Button loading={busy} icon={Check} onClick={()=>catchIt(confirmFacts([modal.fact.id]).then(()=>setModal(null)))}>我已核实，确认这条事实</Button></div></Modal>:modal?.type==='document'?<Modal wide title={modal.document.data.name} onClose={()=>setModal(null)}><pre className="raw-text">{modal.document.data.text}</pre></Modal>:null}</>;
}
function PriceSettings({state,mutate,busy,guard}){const [open,setOpen]=useState(false);const profiles=rows(state,'price_profile'),facts=rows(state,'fact').filter(x=>x.data.status==='confirmed');return <Panel><SectionTitle title="自动报价的程序参数" description="这些内部参数由老板设定，仅供价格程序和财务使用，不会进入客服回复。"><Button icon={Plus} onClick={()=>guard(()=>setOpen(true))}>添加报价规则</Button></SectionTitle><Notice>没有价格规则时，业务员会停在待补充清单；不会猜价格。买家需求完整且匹配产品后，程序计算报价并交法务、财务审查。</Notice>{profiles.length?profiles.map(p=><div className="document-row" key={p.id}><Avatar>价</Avatar><div><strong>{p.data.name}</strong><small>匹配词：{p.data.keywords} · MOQ {p.data.moq} · 毛利底线 {(p.data.floor_bps/100).toFixed(1)}%</small></div><strong>{money(p.data.unit_price_fen,p.data.currency)} / 件</strong><Tag>规则已保存</Tag></div>):<Empty icon={SlidersHorizontal} title="还没有自动报价规则" description="设置产品、成本、售价、起订量与已确认交期，业务员才能生成有依据的报价。"/>}{open?<Modal title="设置产品报价规则" description="价格均以分存储、程序计算。确认的交期来源与产品事实必填。" onClose={()=>setOpen(false)}><form onSubmit={async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.currentTarget));data.unit_cost_fen=Math.round(Number(data.cost)*100);data.unit_price_fen=Math.round(Number(data.price)*100);data.floor_bps=Math.round(Number(data.floor)*100);try{await mutate('/prices',data,'报价规则已保存');setOpen(false)}catch{}}}><div className="form-grid"><Field label="规则名称"><input name="name" required placeholder="316 圆形玻璃夹"/></Field><Field label="匹配关键词（逗号分隔）"><input name="keywords" required placeholder="316,glass clamp,玻璃夹"/></Field><Field label="产品事实"><select name="product_fact_id" required><option value="">选择已确认产品</option>{facts.map(f=><option value={f.id} key={f.id}>{f.data.field}：{f.data.value}</option>)}</select></Field><Field label="交期事实"><select name="lead_fact_id" required><option value="">选择已确认交期</option>{facts.map(f=><option value={f.id} key={f.id}>{f.data.field}：{f.data.value}</option>)}</select></Field><Field label="成本 / 件"><input name="cost" type="number" min="0.01" step="0.01" required/></Field><Field label="售价 / 件"><input name="price" type="number" min="0.01" step="0.01" required/></Field><Field label="币种"><select name="currency"><option>USD</option><option>CNY</option></select></Field><Field label="毛利底线（%）"><input name="floor" type="number" min="0" max="99" defaultValue="15" required/></Field><Field label="最低起订量"><input name="moq" type="number" min="1" defaultValue="100" required/></Field><Field label="默认付款条款"><input name="terms" required placeholder="30% deposit, balance before shipment"/></Field></div><Button loading={busy} type="submit" icon={Check}>确认并保存规则</Button></form></Modal>:null}</Panel>}
const questions=[{key:'market',title:'你想先开拓哪个市场？',description:'先聚焦一个市场，让第一轮验证更清晰。',choices:['马来西亚','新加坡','泰国','其他市场'],type:'choice'}, {key:'products',title:'这次想重点推广哪些产品？',description:'选择你有把握供货、资料最完整的产品。',placeholder:'例如：304 / 316 不锈钢立柱、玻璃夹、扶手管'}, {key:'buyers',title:'你最想接触哪类买家？',description:'这会影响渠道选择、内容与接待话术。',choices:['经销商','工程承包商','装修公司','终端业主','招标项目'],type:'multi'}, {key:'inquiries',title:'每月希望获得多少条有效询盘？',description:'这是你的期望值，不是平台的效果承诺。首批 20 条询盘会帮助校准。',type:'number'}, {key:'deals',title:'每月的成交目标是什么？',description:'可以填成交金额或单数，也可以先不设。',placeholder:'例如：每月 2 单；或先验证询盘质量'}, {key:'channels',title:'希望团队通过哪些渠道工作？',description:'连接后可接收真实询盘，对外动作仍遵守审批规则。',choices:['WhatsApp','Facebook 主页','邮件'],type:'multi'}, {key:'time',title:'每天愿意花多久处理待批事项？',description:'总管会合并待批清单，让你集中处理。',choices:['15 分钟','30 分钟','1 小时'],type:'choice'}, {key:'horizon',title:'希望多久完成这一轮目标？',description:'先做小步验证，再根据真实数据调整策略。',choices:['3 个月','6 个月','1 年'],type:'choice'}];
export function Strategy({state,go,mutate,notify,busy,guard,onSource}){
 const strategies=rows(state,'strategy'),latest=strategies[0];const [editing,setEditing]=useState(!latest),[step,setStep]=useState(0),[answers,setAnswers]=useState(loadAnswers),[target,setTarget]=useState(latest?.data.target||20);
 useEffect(()=>{if(latest)setTarget(latest.data.target)},[latest?.id]);
 useEffect(()=>{if(latest)setEditing(false)},[latest?.id]);
 useEffect(()=>saveAnswers(answers),[answers]);
 const q=questions[step],value=answers[q.key],jobs=state.jobs.filter(j=>j.kind==='strategy'),isRunning=jobs.some(j=>['pending','running'].includes(j.status));
 const hasConfirmedFacts=rows(state,'fact').some(f=>f.data.status==='confirmed'),failedJob=jobs.find(j=>j.status==='blocked');
 if(latest&&!editing){const s=latest.data;return <><SectionTitle title="你的出海方案" description={`总管基于已确认事实与市场情报制定 · 版本 ${s.version} · ${fmt(latest.created_at)}`}><Status status={s.status}/><Button variant="outline" icon={RefreshCw} onClick={()=>setEditing(true)}>调整方向，生成新版</Button></SectionTitle><div className="strategy-layout"><div><Panel className="strategy-summary"><span className="strategy-number">01 / 方向</span><h2>{s.summary}</h2><p>{s.positioning}</p><div className="inline-tags">{s.markets?.map(m=><Tag key={m}>{m}</Tag>)}</div></Panel><Panel><SectionTitle title="市场研判，有据可循" description="事实、线索与缺口分别呈现。离线资料未经实时复核。"/>{s.insights.map((i,n)=><div className="insight-row" key={n}><Tag tone={i.kind==='fact'?'':i.kind==='gap'?'neutral':'amber'}>{i.kind==='fact'?'据来源':i.kind==='gap'?'数据缺口':'线索'}</Tag><div><p>{i.statement}</p><div className="sources">{i.intel_ids?.map(id=><Source key={id} id={id} intel={state.intel} onClick={onSource}/>)}</div></div></div>)}</Panel><Panel><SectionTitle title="先验证假设，再放大投入" description="这些是有待验证的判断，不是已经发生的结果。"/>{s.hypotheses.map((h,i)=><div className="hypothesis-row" key={h.code||i}><span className="hypothesis-id">{h.code||'H'+(i+1)}</span><div><strong>{h.text}</strong><p>{h.validation}</p><div className="sources">{h.evidence_ids?.map(id=><Source key={id} id={id} intel={state.intel} onClick={onSource}/>)}</div></div><Tag tone="amber">待验证</Tag></div>)}</Panel><Panel><SectionTitle title="渠道与内容节奏"/>{[...(s.channel_strategy||[]),...(s.content_plan||[])].map((x,i)=><div className="compact-text" key={i}><Check size={16}/><p>{typeof x==='string'?x:JSON.stringify(x)}</p></div>)}</Panel><Panel><SectionTitle title="需要你配合的事项与风险"/>{[...(s.boss_actions||[]),...(s.risks||[])].map((x,i)=><div className="compact-text" key={i}><AlertTriangle size={15}/><p>{typeof x==='string'?x:JSON.stringify(x)}</p></div>)}</Panel></div><aside><Panel className="sticky"><Tag tone="amber">关口 ⓪ · 战略与目标</Tag><h3>由你确定团队的方向</h3><Field label="每月有效询盘目标"><div className="input-unit"><input type="number" min="1" max="10000" value={target} onChange={e=>setTarget(e.target.value)}/><span>条 / 月</span></div></Field><Notice>{s.expectation}</Notice><p className="muted">第一阶段：先用首批 20 条真实询盘校准。</p>{s.status==='pending'?<Button loading={busy} icon={Check} onClick={()=>catchIt(mutate('/strategy/approve',{id:latest.id,target:Number(target)},'战略已确认，可连接客户渠道'))}>确认方案与目标</Button>:<Button icon={ArrowRight} onClick={()=>go('channels')}>连接客户渠道</Button>}<small className="block-note">策略调整会生成新版本，历史方案与批准记录都会保留。</small></Panel></aside></div></>}
 return <><SectionTitle title="先聊清方向，再让团队行动" description="8 个简短问题，换一份有市场依据、属于你的出海方案。"><Tag>全程免费</Tag></SectionTitle>{isRunning?<Panel><Empty icon={RefreshCw} title="总管正在研究你的出海方向" description="正在对照工厂事实、市场条目与策略假设。生成后会出现在这里，每条洞察都附来源。"><Button variant="outline" onClick={()=>go('team')}>查看团队任务</Button></Empty>{latest?<Button onClick={()=>setEditing(false)}>查看已有方案</Button>:null}</Panel>:<>{failedJob?<Notice tone="warning">上次生成未完成：{failedJob.error||'未知原因'}。<button className="text-link" onClick={()=>catchIt(mutate('/jobs/retry',{id:failedJob.id},'已重新派单，总管正在按原答案制定方案'))}>按原答案重试</button></Notice>:null}{!hasConfirmedFacts?<Notice tone="warning">先确认至少一条产品事实，总管才能有据可依地制定方案。<button className="text-link" onClick={()=>go('knowledge')}>去确认事实</button></Notice>:null}<Panel className="question-panel"><div className="question-progress"><span>关于你的出海计划</span><strong>{String(step+1).padStart(2,'0')} <small>/ 08</small></strong></div><div className="progress-track"><div style={{width:(step+1)/8*100+'%'}}/></div><div className="question-body"><h2>{q.title}</h2><p>{q.description}</p>{q.choices?<div className="choice-grid">{q.choices.map(c=><button key={c} className={(Array.isArray(value)?value.includes(c):value===c)?'chosen':''} onClick={()=>setAnswers(a=>({...a,[q.key]:q.type==='multi'?(a[q.key].includes(c)?a[q.key].filter(x=>x!==c):[...a[q.key],c]):c}))}><span>{c}</span><span className="choice-check">{(Array.isArray(value)?value.includes(c):value===c)?<Check size={15}/>:null}</span></button>)}</div>:<input className="question-input" type={q.type==='number'?'number':'text'} min={q.type==='number'?1:undefined} max={q.type==='number'?10000:undefined} value={value} placeholder={q.placeholder} onChange={e=>setAnswers(a=>({...a,[q.key]:e.target.value}))}/>}<div className="question-actions"><Button variant="ghost" disabled={step===0} icon={ArrowLeft} onClick={()=>setStep(step-1)}>上一步</Button>{step<7?<Button icon={ArrowRight} onClick={()=>{if(q.key==='inquiries'&&(!Number.isInteger(Number(value))||Number(value)<1||Number(value)>10000))return;setStep(step+1)}}>下一步</Button>:<Button loading={busy} icon={ArrowRight} onClick={()=>{if(!guard())return;if(!hasConfirmedFacts){notify('请先确认至少一条产品事实，再制定出海方案',true);go('knowledge');return;}catchIt(mutate('/strategy',answers,'总管已接单，正在制定方案').then(()=>setEditing(false)))}}>生成我的出海方案</Button>}</div></div><div className="question-footer"><BookOpen size={16}/>有数据的标明来源，没数据的诚实告诉你。我们不承诺询盘数量。</div></Panel></>}{!latest?<div className="strategy-preview"><div><span>01</span><strong>了解你的工厂</strong><p>以你确认过的产品事实为依据</p></div><div><span>02</span><strong>对照目标市场</strong><p>区分市场事实、线索与数据缺口</p></div><div><span>03</span><strong>制定验证计划</strong><p>先让真实询盘验证每一条假设</p></div></div>:null}</>;
}
export function Team({state,go,mutate,notify,busy,guard}){
 const [agent,setAgent]=useState('manager'),[text,setText]=useState(''),[tab,setTab]=useState('chat');const current=state.agents.find(a=>a.id===agent),chats=rows(state,'chat').filter(c=>c.data.role===agent||c.data.agent===agent).slice().reverse();const jobs=state.jobs.filter(j=>agent==='manager'||j.agent===agent);
 return <div className="team-layout"><aside className="agent-sidebar"><button className="team-all" onClick={()=>setAgent('manager')}><Avatar large><Users size={20}/></Avatar><div><strong>外贸团队</strong><small>7 位 AI 同事 · 你</small></div></button><span className="rail-label">认识一位同事</span>{state.agents.map(a=><button className={'agent-row '+(agent===a.id?'selected':'')} key={a.id} onClick={()=>setAgent(a.id)}><Avatar tone={a.id}>{a.tag}</Avatar><div><strong>{a.name}<span>{a.role}</span></strong><small>{a.free||state.entitled?(state.capabilities.mimo?'已就绪，等待工作':'等待模型配置'):'开通后上岗'}</small></div>{!a.free&&!state.entitled?<LockKeyhole size={13}/>:null}</button>)}<Button variant='outline small' icon={RefreshCw} loading={busy} onClick={()=>{if(guard())catchIt(mutate('/manager/run',{},'总管已检查目标缺口并路由下一步任务'))}}>检查目标缺口</Button><div className="rail-foot"><ShieldCheck size={16}/><p>AI 同事不持有支付工具<br/>所有对外操作经过出站网关</p></div></aside><Panel className="chat-panel"><header><div><strong>{current.name}</strong><small>{current.goal}</small></div><div className="segmented"><button className={tab==='chat'?'selected':''} onClick={()=>setTab('chat')}>对话</button><button className={tab==='tasks'?'selected':''} onClick={()=>setTab('tasks')}>任务 <span>{jobs.length}</span></button></div></header>{tab==='chat'?<><div className="chat-messages">{chats.length?chats.map(c=><div key={c.id} className={'chat-message '+(c.data.role==='boss'?'mine':'')}><Avatar>{c.data.role==='boss'?'你':current.tag}</Avatar><div><span className="message-name">{c.data.role==='boss'?'你':current.name} <small>{fmt(c.created_at)}</small></span><div className="bubble">{c.data.text}</div>{c.data.source_ids?.length?<small className="message-source">依据：{c.data.source_ids.map(id=>rows(state,'fact').find(f=>f.id===id)?.data.field||id.slice(0,8)).join('、')}</small>:null}</div></div>):<div className="chat-welcome"><Avatar large>{current.tag}</Avatar><h2>我是你的{current.name}。</h2><p>{current.goal}。<br/>直接问我，或者从下面的问题开始。</p><div className="chat-suggestions">{['我的资料还缺少什么？','下一步应该做什么？','有哪些任务需要我拍板？'].map(q=><button key={q} onClick={()=>setText(q)}>{q}<ArrowUpRight size={14}/></button>)}</div></div>}</div><form className="chat-composer" onSubmit={async e=>{e.preventDefault();if(!guard())return;try{await mutate('/chat',{agent,text});setText('')}catch{}}}><div><textarea placeholder={`和${current.name}聊聊你的业务…`} value={text} onChange={e=>setText(e.target.value)} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();e.currentTarget.form.requestSubmit()}}} maxLength={5000}/><Button type="submit" icon={Send} disabled={!text.trim()||(!current.free&&!state.entitled)} loading={busy}><span className="sr-only">发送</span></Button></div><small><ShieldCheck size={12}/>对话不代替审批。价格、对外内容、订单，由你确认。</small></form></>:<div className="tasks-list">{jobs.length?jobs.map(j=><div className="task-row" key={j.id}><div><strong>{{parse:'整理产品事实',strategy:'制定出海方案',reply:'接待客户询盘',content:'起草内容',report:'经营简报',review_quote:'报价审查',auto_quote:'生成报价',send:'发送消息'}[j.kind]||j.kind}</strong><small>{fmt(j.created_at)} · {state.agents.find(a=>a.id===j.agent)?.name} · 执行 {j.attempts} 次</small>{j.error?<p className="error-text">{j.error}</p>:null}</div><Status status={j.status}/>{j.status==='blocked'?<Button variant="outline small" icon={RefreshCw} loading={busy} onClick={()=>catchIt(mutate('/jobs/retry',{id:j.id},'已重新派单'))}>重试</Button>:null}</div>):<Empty title="每一项任务，都会留下记录" description="上传资料、接收询盘或创建内容后，可以在这里查看每次交接与执行结果。"/>}</div>}</Panel><aside className="team-right"><Panel><h3>你可以这样问</h3>{['我们有 SGS 检测报告吗？','现在哪些报价需要我批准？','为什么推荐先做柔佛？','帮我整理今天的工作进展'].map(q=><button className="prompt-row" key={q} onClick={()=>{setText(q);setTab('chat')}}><MessageCircle size={13}/>{q}</button>)}</Panel><Panel><h3>团队的工作规则</h3>{['事实必须有来源，缺资料就提出问题','价格与毛利由程序计算','报价经过法务、财务和你三方确认','每次派单、交接、发送都有记录'].map(t=><div className="rule" key={t}><Check size={14}/><span>{t}</span></div>)}</Panel><Panel className="teal-panel"><h3>让团队开始下一项工作</h3><Button variant="outline" icon={FileText} onClick={()=>go('knowledge')}>完善事实库</Button><Button variant="outline" icon={Target} onClick={()=>go('strategy')}>制定出海方案</Button></Panel></aside></div>;
}
export function Business({state,go,mutate,notify,busy,guard}){
 const [tab,setTab]=useState('inquiries'),[selected,setSelected]=useState(null),[query,setQuery]=useState(''),[modal,setModal]=useState(null),[filter,setFilter]=useState('all');
 const customers=rows(state,'customer'),quotes=rows(state,'quote'),orders=rows(state,'order'),list=(tab==='inquiries'?customers:tab==='quotes'?quotes:orders).filter(r=>JSON.stringify(r.data).toLowerCase().includes(query.toLowerCase())).filter(r=>filter==='all'||(filter==='pending'&&['pending_boss','blocked'].includes(r.data.status)));
 const chosen=list.find(c=>c.id===selected)||list[0],customer=tab==='inquiries'?chosen:customers.find(c=>c.id===chosen?.data.customer_id),messages=rows(state,'message').filter(m=>m.data.customer_id===customer?.id).reverse(),outboxes=rows(state,'outbox').filter(o=>o.data.customer_id===customer?.id&&o.data.status!=='sent');
 const customerName=r=>customers.find(c=>c.id===r?.data.customer_id)?.data.name||'客户';
 return <><div className="business-toolbar"><div className="tabs-line">{[['inquiries','询盘',customers],['quotes','报价',quotes],['orders','订单',orders]].map(([id,label,data])=><button key={id} className={tab===id?'selected':''} onClick={()=>{setTab(id);setSelected(null);setFilter('all')}}>{label}<Tag tone="neutral">{data.length}</Tag></button>)}</div><Button icon={Plus} variant="outline" onClick={()=>guard(()=>setModal('import'))}>录入询盘</Button></div><div className="business-layout"><aside className="conversation-list"><label className="search"><Search size={17}/><input placeholder="搜索客户、公司或内容" value={query} onChange={e=>setQuery(e.target.value)}/></label><div className="filter-row"><button className={filter==='all'?'selected':''} onClick={()=>setFilter('all')}>全部 <span>{list.length}</span></button><button className={filter==='pending'?'selected':''} onClick={()=>setFilter('pending')}>待处理</button></div>{!state.channels.length?<div className="channel-hint"><span><Globe size={13}/> 连接渠道，自动接收询盘</span><button onClick={()=>go('channels')}>去连接 <ChevronRight size={13}/></button></div>:null}<div className="conversations">{list.map(r=><button className={'conversation '+(r.id===chosen?.id?'selected':'')} key={r.id} onClick={()=>setSelected(r.id)}><Avatar>{(tab==='inquiries'?r.data.name:customerName(r)).slice(0,2).toUpperCase()}</Avatar><div><div className="conversation-top"><strong>{tab==='inquiries'?r.data.name:customerName(r)}</strong><small>{fmt(r.created_at).slice(0,5)}</small></div>{tab==='inquiries'?<><p>{r.data.last_text}</p><div className="inline-tags"><Tag tone="neutral">{r.data.channel==='whatsapp'?'WhatsApp':r.data.channel==='facebook'?'Facebook':'邮件'}</Tag><Tag tone={r.data.origin==='live'?'':'amber'}>{r.data.origin==='live'?'真实接入':r.data.origin==='simulation'?'模拟':'手动录入'}</Tag>{r.data.opted_out?<Tag tone="red">已退订</Tag>:null}</div></>:<><p>{tab==='quotes'?`报价 v${r.data.version} · ${money(r.data.calculation.total_fen,r.data.calculation.currency)}`:money(r.data.total_fen,r.data.currency)}</p><Status status={r.data.status}/></>}</div></button>)}</div></aside><Panel className="deal-detail">{!chosen?<Empty icon={BriefcaseBusiness} title={tab==='inquiries'?'下一段生意，从一条真实询盘开始':tab==='quotes'?'每一份报价，都经过认真核对':'成交不是终点，交付也有记录'} description={tab==='inquiries'?'连接 WhatsApp 或 Facebook，接收买家的真实消息。已有的询盘也可以手动录入。':tab==='quotes'?'先确认产品、价格规则和客户需求，业务员才能起草有依据的报价。':'买家确认报价后，由你确认订单。签署、收款和发货均由你记录凭证。'}><Button icon={ArrowRight} onClick={()=>go(tab==='inquiries'?'channels':'knowledge')}>{tab==='inquiries'?'连接客户渠道':'完善商品资料'}</Button></Empty>:<><header className="deal-header"><Avatar large>{customer?.data.name?.slice(0,2).toUpperCase()||'客'}</Avatar><div><h2>{customer?.data.name||'客户'}</h2><small>{tab==='inquiries'?(customer.data.origin==='live'?'来自官方渠道的真实消息':'手动录入，不会通过官方渠道自动发送'):'每个版本与审批记录均可追溯'}</small></div><Button variant="outline small" onClick={()=>setModal({type:'customer',customer})}>客户档案</Button></header>{tab==='inquiries'?<><div className="buyer-messages">{messages.map(m=><div className={'buyer-message '+(m.data.direction==='out'?'out':'')} key={m.id}><div><strong>{m.data.direction==='in'?customer.data.name:'外贸团队'}</strong><Tag tone="neutral">{m.data.channel}</Tag><small>{fmt(m.created_at)}</small></div><p>{m.data.text}</p>{m.data.direction==='out'?<small>{m.data.delivery_status==='delivered'?'已送达':m.data.delivery_status==='read'?'已读':'已提交渠道'}</small>:null}</div>)}{quotes.filter(q=>q.data.customer_id===customer.id).map(q=><button className="thread-event" key={q.id} onClick={()=>{setTab('quotes');setSelected(q.id)}}><FileText size={14}/>报价 v{q.data.version} {money(q.data.calculation.total_fen,q.data.calculation.currency)} <Status status={q.data.status}/><ChevronRight size={14}/></button>)}</div><div className="inquiry-actions"><Button variant="outline" icon={Plus} onClick={()=>setModal({type:'quote',customer})}>起草报价</Button><span>需求完整且已配置价格规则时，业务员会自动接手报价。</span></div>{outboxes.map(o=><div className="outbox-draft" key={o.id}><div className="draft-head"><Tag>AI 草稿</Tag><Status status={o.data.status}/><span>{o.data.channel}</span></div><p>{o.data.text}</p>{o.data.block_reasons?<Notice tone="warning">{o.data.block_reasons.join('；')}</Notice>:null}{customer.data.origin==='manual'?<Button variant="outline small" icon={Copy} onClick={async()=>{try{await navigator.clipboard.writeText(o.data.text);notify('已复制，请在买家原渠道核对后发送')}catch{notify('复制失败，请手动选择文本',true)}}}>复制草稿</Button>:o.data.status==='pending_boss'?<Button variant="small" loading={busy} icon={Check} onClick={()=>catchIt(mutate('/approve',{id:o.id},'已批准，系统将经网关发送'))}>批准发送</Button>:null}</div>)}</>:tab==='quotes'?<QuoteDetail quote={chosen} {...{state,mutate,busy,notify,setModal,customer}}/>:<OrderDetail order={chosen} {...{state,mutate,busy,setModal}}/>}</>}</Panel><aside className="business-right">{customer?<><Panel><SectionTitle title="客户档案"/><dl className="details-list"><dt>联系人</dt><dd>{customer.data.name}</dd><dt>渠道</dt><dd>{customer.data.channel}</dd><dt>类型</dt><dd>{rows(state,'requirement').find(r=>r.data.customer_id===customer.id)?.data.buyer_type||'尚未确认'}</dd><dt>来源</dt><dd>{customer.data.origin==='live'?'官方渠道真实接入':'手动录入'}</dd><dt>状态</dt><dd>{customer.data.opted_out?'已退订，禁止发送':'可跟进'}</dd></dl></Panel><Panel><SectionTitle title="往来一览"/><div className="mini-stats"><div><strong>{messages.filter(m=>m.data.direction==='in').length}</strong><span>来信</span></div><div><strong>{quotes.filter(q=>q.data.customer_id===customer.id).length}</strong><span>报价版本</span></div><div><strong>{orders.filter(q=>q.data.customer_id===customer.id).length}</strong><span>已确认订单</span></div></div></Panel>{rows(state,'requirement').filter(r=>r.data.customer_id===customer.id).slice(0,1).map(r=><Panel key={r.id}><h3>AI 读出的需求</h3><dl className="details-list">{[['产品','product'],['材质','material'],['数量','quantity'],['目的港','port'],['交期','delivery'],['付款','payment']].map(([l,k])=><React.Fragment key={k}><dt>{l}</dt><dd>{r.data[k]||'等待买家确认'}</dd></React.Fragment>)}</dl>{r.data.missing?.length?<Notice tone="warning">待补充：{r.data.missing.join('、')}</Notice>:null}</Panel>)}</>:<Panel className="promise-panel"><ShieldCheck size={28}/><h3>生意有进展，<br/>记录有来处。</h3><p>询盘、报价、批准到订单，<br/>一条时间线看清来龙去脉。</p></Panel>}<div className="rail-disclaimer"><LockKeyhole size={16}/><p>平台仅收取软件订阅费。买家货款、合同签署和物流由你在线下完成，平台保留你确认的记录。</p></div></aside></div>{modal==='import'?<Modal title="录入一条已有询盘" description="录入内容标记为“手动录入”，不会冒充真实渠道消息，也不会自动对外发送。" onClose={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();try{const form=new FormData(e.currentTarget);const out=await mutate('/inbox/import',{...Object.fromEntries(form),simulation:form.get('simulation')==='on'},'询盘已录入');setSelected(out.customer_id);setTab('inquiries');setModal(null)}catch{}}}><Field label="客户或公司名称"><input name="name" required placeholder="买家的真实名称"/></Field><Field label="原始渠道"><select name="channel"><option value="whatsapp">WhatsApp</option><option value="facebook">Facebook 主页</option><option value="email">邮件</option></select></Field><Field label="买家原话"><textarea name="text" rows={5} required placeholder="粘贴询盘原文，保留规格、数量与目的港等信息"/></Field><label className='checkbox-label'><input name='simulation' type='checkbox'/>这是一条模拟询盘，仅用于走查</label><Button loading={busy} type="submit">保存询盘</Button></form></Modal>:modal?.type==='quote'?<QuoteForm {...{state,mutate,busy,customer:modal.customer}} onClose={()=>setModal(null)}/>:modal?.type==='customer'?<Modal title="客户档案" onClose={()=>setModal(null)}><dl className="details-list"><dt>名称</dt><dd>{modal.customer?.data.name}</dd><dt>渠道</dt><dd>{modal.customer?.data.channel}</dd><dt>渠道用户 ID</dt><dd className="break-all">{modal.customer?.data.external_id}</dd><dt>最近来信</dt><dd>{fmt(modal.customer?.data.last_message_at)}</dd><dt>回复窗口至</dt><dd>{fmt(modal.customer?.data.window_expires_at)}</dd><dt>状态</dt><dd>{modal.customer?.data.opted_out?'已退订':'可跟进'}</dd></dl></Modal>:modal?.type==='order'?<Modal title="确认订单" description="请先确认买家与我们接受的是同一版报价。此操作只建立成交记录，不代表收到货款。" onClose={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await mutate('/order',{quote_id:modal.quote.id,buyer_confirmation:f.get('buyer_confirmation')},'订单已确认');setTab('orders');setSelected(null);setModal(null)}catch{}}}><Notice>报价 v{modal.quote.data.version} · {money(modal.quote.data.calculation.total_fen,modal.quote.data.calculation.currency)}</Notice><Field label="买家确认原文或凭证编号"><textarea required name="buyer_confirmation" placeholder="例如：买家于 WhatsApp 确认报价 v2，消息编号…"/></Field><Button loading={busy} type="submit" icon={Check}>确认订单并记录</Button></form></Modal>:null}</>;
}
function QuoteForm({state,mutate,busy,customer,onClose}){const facts=rows(state,'fact').filter(f=>f.data.status==='confirmed');return <Modal wide title="起草一份有依据的报价" description="业务员调用价格程序；金额、毛利与底线由程序计算，之后进入双钥匙审查。" onClose={onClose}><form onSubmit={async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));b.customer_id=customer.id;b.unit_cost_fen=Math.round(Number(b.cost)*100);b.unit_price_fen=Math.round(Number(b.price)*100);b.freight_fen=Math.round(Number(b.freight)*100);b.floor_bps=Math.round(Number(b.floor)*100);try{await mutate('/quote',b,'报价已计算，正在等待审查');onClose()}catch{}}}><div className="form-grid"><Field label="客户"><input readOnly value={customer.data.name}/></Field><Field label="产品事实"><select name="product_fact_id" required><option value="">选择已确认的产品</option>{facts.map(f=><option key={f.id} value={f.id}>{f.data.field}：{f.data.value}</option>)}</select></Field><Field label="数量"><input name="quantity" type="number" min="1" step="1" required/></Field><Field label="币种"><select name="currency"><option>USD</option><option>CNY</option></select></Field><Field label="单位成本（内部）"><input name="cost" type="number" min="0.01" step="0.01" required/></Field><Field label="单位售价"><input name="price" type="number" min="0.01" step="0.01" required/></Field><Field label="运费（同币种）"><input name="freight" type="number" min="0" step="0.01" defaultValue="0" required/></Field><Field label="最低毛利（%）"><input name="floor" type="number" min="0" max="99" defaultValue="15" required/></Field><Field label="已确认交期"><select name="lead_fact_id" required><option value="">选择事实来源</option>{facts.map(f=><option key={f.id} value={f.id}>{f.data.field}：{f.data.value}</option>)}</select></Field><Field label="贸易与付款条款"><input name="terms" required placeholder="FOB Shanghai; 30% deposit, 70% before shipment"/></Field></div><Notice>不能满足的条款请先与买家澄清。确认报价仍需法务、财务通过及你批准。</Notice><Button loading={busy} type="submit" icon={ArrowRight}>计算并提交审查</Button></form></Modal>}
function QuoteDetail({quote:q,state,mutate,busy,notify,setModal,customer}){const d=q.data,c=d.calculation;return <div className="quote-content"><div className="quote-title"><div><Tag tone="neutral">报价 v{d.version}</Tag><h2>{money(c.total_fen,c.currency)}</h2><small>数量 {c.quantity} · 单价 {money(c.unit_price_fen,c.currency)}</small></div><Status status={d.status}/></div><div className="quote-checks"><div className={d.finance_pass?'passed':'not-passed'}><CheckCheck size={17}/><strong>财务</strong><span>{d.finance_pass?'毛利通过':'低于底线'}</span></div><div className={d.legal_pass?'passed':'not-passed'}><ShieldCheck size={17}/><strong>法务</strong><span>{d.legal_pass?'审查通过':d.status==='reviewing'?'正在审查':'需要处理'}</span></div><div className={d.boss_approved?'passed':'pending-check'}><UserIcon/><strong>老板</strong><span>{d.boss_approved?'你已批准':'等待你批准'}</span></div></div><Notice tone={c.pass?'':'warning'}>程序计算毛利 {(c.margin_bps/100).toFixed(2)}%，底线 {(c.floor_bps/100).toFixed(2)}%。内部成本 {money(c.unit_cost_fen,c.currency)} / 件。成本与底线不会出现在买家报价中。</Notice><pre className="quote-text">{d.text}</pre>{d.legal_review?<div className="review-note"><strong>法务审查意见</strong><p>{d.legal_review.note}</p>{d.legal_review.issues?.map((i,n)=><p key={n}>{typeof i==='string'?i:JSON.stringify(i)}</p>)}</div>:null}<div className="quote-bottom">{d.status==='pending_boss'?<Button icon={Check} loading={busy} onClick={()=>catchIt(mutate('/approve',{id:q.id},'报价已批准；真实接入的会话将由网关发送'))}>批准报价</Button>:d.boss_approved?<><Button icon={Check} onClick={()=>setModal({type:'order',quote:q})}>买家已确认，建立订单</Button><Button variant="outline" icon={Copy} onClick={async()=>{try{await navigator.clipboard.writeText(d.text);notify('已复制已批准的报价')}catch{notify('复制失败，请手动复制',true)}}}>复制报价</Button></>:null}<Button variant="outline" icon={Plus} onClick={()=>setModal({type:'quote',customer})}>调整条款，生成新版</Button></div><small className="muted">每个版本单独审查、批准。价格和条款发生变化后，需要重新审批。</small></div>}
const UserIcon=()=> <Users size={17}/>;
function OrderDetail({order,state,mutate,busy}){const [update,setUpdate]=useState(false);const d=order.data;return <div className="order-content"><div className="quote-title"><div><Tag tone={d.origin==='simulation'?'amber':''}>{d.origin==='simulation'?'模拟订单':d.origin==='manual'?'手动来源 · 你确认的订单':'你确认的订单'}</Tag><h2>{money(d.total_fen,d.currency)}</h2><small>订单 #{order.id.slice(0,8)} · {fmt(order.created_at)}</small></div><Status status={d.status}/></div><Notice>合同签署、收款和物流在平台外完成；以下是你确认的业务记录。</Notice><h3>订单进度与来龙去脉</h3><div className="timeline">{d.timeline?.map((e,i)=><div className="timeline-item" key={i}><span><Check size={14}/></span><div><strong>{names[e.status]||e.status}</strong><small>{fmt(e.at)} · 你记录</small><p>{e.note}</p></div></div>)}</div><Button variant="outline" icon={Plus} onClick={()=>setUpdate(true)}>记录下一步进展</Button>{update?<Modal title="记录订单进展" description="请依据实际发生的业务填写，记录会保留时间与操作人。" onClose={()=>setUpdate(false)}><form onSubmit={async e=>{e.preventDefault();try{await mutate('/order/update',{...Object.fromEntries(new FormData(e.currentTarget)),id:order.id},'订单进展已记录');setUpdate(false)}catch{}}}><Field label="进度"><select name="status">{['contract_signed','deposit_received','production','balance_received','shipped','completed'].map(s=><option value={s} key={s}>{names[s]}</option>)}</select></Field><Field label="说明与凭证编号"><textarea name="note" required placeholder="填写合同编号、银行流水或提单号等依据。"/></Field><Button type="submit" loading={busy}>保存记录</Button></form></Modal>:null}</div>}
export function Growth({state,go,mutate,notify,busy,guard,onSource}){
 const [tab,setTab]=useState('content'),[modal,setModal]=useState(null);const content=rows(state,'content'),strategy=rows(state,'strategy').find(s=>s.data.status==='approved');
 return <><SectionTitle title="用真实内容，开启下一段对话" description="运营起草，法务审查，你批准后发布。再用真实询盘验证策略。"><Button icon={Plus} loading={busy} onClick={()=>{if(guard())catchIt(mutate('/task',{kind:'content'},'运营已接单，草稿会在审查后出现'))}}>起草 Facebook 帖子</Button></SectionTitle><div className="tabs-line"><button className={tab==='content'?'selected':''} onClick={()=>setTab('content')}>内容工作台 <Tag tone="neutral">{content.length}</Tag></button><button className={tab==='hypotheses'?'selected':''} onClick={()=>setTab('hypotheses')}>策略假设与验证</button></div>{tab==='content'?content.length?<div className="content-grid">{content.map(c=><Panel key={c.id} className="content-card"><header><span className="channel-logo facebook">f</span><div><strong>{c.data.title||'Facebook 帖子草稿'}</strong><small>运营 · {fmt(c.created_at)}</small></div><Status status={c.data.status}/></header><p className="post-text">{c.data.text}</p><div className="post-sources"><FileText size={14}/>{c.data.source_ids?.length?`依据 ${c.data.source_ids.length} 条已确认事实`:'无产品事实断言'}</div>{c.data.legal_review?<div className="legal-note"><ShieldCheck size={15}/><span>{c.data.legal_review.pass?'法务审查通过':c.data.legal_review.issues?.join('；')||'需要修改'}</span></div>:null}<footer>{c.data.status==='pending_boss'?<Button variant="small" loading={busy} icon={Check} onClick={()=>catchIt(mutate('/approve',{id:c.id},'内容已批准，请复制到 Facebook 手动发布'))}>批准内容</Button>:null}{c.data.status==='approved'?<><Button variant="outline small" icon={Copy} onClick={async()=>{try{await navigator.clipboard.writeText(c.data.text);notify('已复制，前往你的 Facebook 主页发布')}catch{notify('复制失败，请手动复制',true)}}}>复制内容</Button><Button variant="small" icon={ExternalLink} onClick={()=>setModal(c)}>记录发布</Button></>:null}{c.data.status==='published'?<a className="text-link" target="_blank" rel="noreferrer" href={c.data.published_url}>查看已发布帖子 <ExternalLink size={14}/></a>:null}</footer></Panel>)}</div>:<Panel><Empty icon={Target} title="内容要有事实，也要有方向" description="确认工厂事实和出海战略后，运营会按你的方向起草内容。没有证据的认证、价格与保修承诺不会出现在帖子里。"><Button variant="outline" icon={ArrowRight} onClick={()=>go(strategy?'knowledge':'strategy')}>{strategy?'查看事实库':'制定出海方案'}</Button></Empty></Panel>:<Panel><SectionTitle title="从判断到证据，逐条验证" description="需要足够的真实询盘才能判断，人工录入与真实接入分别记录。"/>{strategy?.data.hypotheses?.length?strategy.data.hypotheses.map((h,i)=><div className="hypothesis-row" key={h.code||i}><span className="hypothesis-id">{h.code||'H'+(i+1)}</span><div><strong>{h.text}</strong><p>{h.validation}</p><div className="sources">{h.evidence_ids?.map(id=><Source key={id} id={id} intel={state.intel} onClick={onSource}/>)}</div></div><Tag tone="amber">待验证</Tag></div>):<Empty icon={BookOpen} title="先确认战略，才能验证方向" description="总管会为每条市场假设列明依据和验证标准。"><Button onClick={()=>go('strategy')}>制定出海方案</Button></Empty>}<Notice>当前真实接入客户数：{rows(state,'customer').filter(c=>c.data.origin==='live').length}。验证结论由周报提出，目标和策略的变化仍需你确认。</Notice></Panel>}{modal?<Modal title="记录真实发布链接" description="平台不代替你自动发布 Facebook 主页帖子。请完成发布后粘贴链接，保持数据可追溯。" onClose={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();try{await mutate('/content/published',{id:modal.id,url:new FormData(e.currentTarget).get('url')},'发布记录已保存');setModal(null)}catch{}}}><Field label="Facebook 帖子链接"><input type="url" name="url" placeholder="https://www.facebook.com/…" required/></Field><Button loading={busy} type="submit">保存发布记录</Button></form></Modal>:null}</>;
}
const ACTIONS={'goal.gap_routed':'总管发现目标缺口并派发补救任务','factory.registered':'建立工厂工作区','document.uploaded':'上传原始资料','model.completed':'完成模型调用','ticket.created':'总管派发工单','ticket.completed':'完成工单','ticket.escalated':'异常升级，等待处理','ticket.retry_scheduled':'安排自动重试','ticket.retried':'老板重新派单','gate.1.fact_confirmed':'老板确认产品事实','fact.proposed':'提交事实草稿','gate.0.strategy_approved':'老板确认战略与目标','price.calculated':'程序计算报价','quote.reviewed':'法务审查报价','gate.3.quote_approved':'老板批准报价','gate.2.outbound_approved':'老板批准对外内容','gate.4.order_confirmed':'老板确认订单','message.received':'收到客户消息','message.sent':'网关发送消息','message.failed':'渠道发送失败','message.uncertain':'发送结果待核对','outbox.reviewed':'法务审查回复','channel.authorized':'授权连接渠道','channel.disconnected':'断开渠道连接','customer.opted_out':'买家退订，网关停止联系','content.publication_recorded':'记录手动发布','order.progress_recorded':'记录订单进展','payment.created':'创建订阅支付订单','subscription.activated':'到账验签，开通订阅','invoice.requested':'提交开票申请','price_profile.confirmed':'老板确认报价参数'};
export function Insights({state,go,mutate,busy,guard}){
 const [tab,setTab]=useState('overview'),[log,setLog]=useState(null),[actor,setActor]=useState('all');const customers=rows(state,'customer'),real=customers.filter(c=>c.data.origin==='live'),reports=rows(state,'report'),logs=state.logs.filter(l=>actor==='all'||l.actor===actor);
 return <><SectionTitle title="看清结果，也看清来龙去脉" description="只呈现实际发生的业务。没有数据时，不用预测填空。"><a className="btn outline" href="/api/export"><Download size={16}/>导出运行记录</a><Button loading={busy} icon={Plus} onClick={()=>{if(guard())catchIt(mutate('/task',{kind:'report',period:'daily'},'总管正在整理经营简报'))}}>生成经营简报</Button></SectionTitle><div className="tabs-line">{[['overview','经营概览'],['reports','简报与周报'],['audit','操作记录'],['intel','市场情报']].map(([id,label])=><button key={id} className={tab===id?'selected':''} onClick={()=>setTab(id)}>{label}</button>)}</div>{tab==='overview'?<><div className="metric-grid">{[['真实接入客户',real.length,'来自官方渠道的客户'],['待你批准',rows(state,'quote').filter(q=>q.data.status==='pending_boss').length+rows(state,'content').filter(q=>q.data.status==='pending_boss').length,'审查通过后进入待批'],['已确认订单',rows(state,'order').length,'由你确认并留有记录']].map(([label,value,description])=><Panel className="metric" key={label}><span>{label}</span><strong>{value}</strong><small>{description}</small></Panel>)}</div><div className="two-col"><Panel><SectionTitle title="询盘来自哪里" description="按真实接入客户数统计，人工录入单独保留。"/>{['whatsapp','facebook','email'].map((c,i)=>{const n=real.filter(x=>x.data.channel===c).length;return <div className="bar-row" key={c}><span>{['WhatsApp','Facebook','邮件'][i]}</span><div><span style={{width:(real.length?n/real.length*100:0)+'%'}}/></div><strong>{n}</strong></div>})}<small className="block-note">手动录入客户：{customers.length-real.length} 位，未计入真实渠道数据。</small></Panel><Panel><SectionTitle title="流程进展" description="这是当前记录数量，不代表市场转化率。"/>{[['已确认产品事实',rows(state,'fact').filter(f=>f.data.status==='confirmed').length],['报价版本',rows(state,'quote').length],['老板确认订单',rows(state,'order').length],['已记录发布内容',rows(state,'content').filter(c=>c.data.status==='published').length]].map(([l,n])=><div className="count-row" key={l}><span>{l}</span><strong>{n}</strong></div>)}</Panel></div></>:tab==='reports'?reports.length?<div className="reports">{reports.map(r=><Panel key={r.id}><SectionTitle title={r.data.title||'经营简报'} description={fmt(r.created_at)}><Tag>{r.data.period==='weekly'?'周报':'日简报'}</Tag></SectionTitle><p className="report-summary">{r.data.summary}</p>{[['本期观察','findings'],['需要处理','blockers'],['下一步建议','next_actions']].map(([l,k])=><div className="report-section" key={k}><h4>{l}</h4>{r.data[k]?.length?r.data[k].map((t,i)=><p key={i}>{typeof t==='string'?t:JSON.stringify(t)}</p>):<p className="muted">暂无记录</p>}</div>)}{r.data.hypothesis_updates?.map((h,i)=><div className="compact-text" key={i}><Tag tone="amber">{h.code} · {h.status==='supported'?'获得支持':h.status==='refuted'?'待调整':'待验证'}</Tag><p>{h.reason}</p></div>)}</Panel>)}</div>:<Panel><Empty icon={FileText} title="把每天的进展，整理成一页简报" description="总管会基于真实询盘、审批、报价和订单，告诉你卡在哪里、下一步做什么。"/></Panel>:tab==='audit'?<Panel className="audit-panel"><div className="table-toolbar"><span><Activity size={16}/> 每个动作都有时间、操作人和关联依据</span><select aria-label="筛选操作人" value={actor} onChange={e=>setActor(e.target.value)}><option value="all">全部操作人</option>{['boss',...state.agents.map(a=>a.id),'gateway','channel-adapter','billing'].map(a=><option key={a} value={a}>{a==='boss'?'老板':state.agents.find(x=>x.id===a)?.name||a}</option>)}</select></div>{logs.length?<div className="table-wrap"><table><thead><tr><th>时间</th><th>执行人</th><th>动作</th><th>关联对象</th><th></th></tr></thead><tbody>{logs.map(l=><tr key={l.id}><td className="nowrap">{fmt(l.created_at)}</td><td>{l.actor==='boss'?'你':state.agents.find(a=>a.id===l.actor)?.name||{'gateway':'出站网关','billing':'计费程序','channel-adapter':'渠道适配器'}[l.actor]||l.actor}</td><td>{ACTIONS[l.action]||l.action}</td><td className="mono">{l.entity?.slice(0,12)}</td><td><button className="text-link" onClick={()=>setLog(l)}>查看依据 <ChevronRight size={13}/></button></td></tr>)}</tbody></table></div>:<Empty title="团队开始工作后，记录会出现在这里" description="老板决策与 AI 执行分别记录，可随时导出核对。"/>}</Panel>:<IntelLibrary state={state}/>} {log?<Modal wide title={ACTIONS[log.action]||log.action} description={fmt(log.created_at)+' · '+log.actor} onClose={()=>setLog(null)}><dl className="details-list"><dt>关联对象</dt><dd className="mono">{log.entity}</dd><dt>记录编号</dt><dd className="mono">{log.id}</dd></dl><pre className="raw-text">{JSON.stringify(JSON.parse(log.detail),null,2)}</pre></Modal>:null}</>;
}
function IntelLibrary({state}){const [category,setCategory]=useState('all'),[query,setQuery]=useState('');const entries=state.intel.filter(e=>(category==='all'||e.id.startsWith(category))&&JSON.stringify(e).toLowerCase().includes(query.toLowerCase()));return <><Notice>来自你上传的《马来西亚楼梯五金市场情报包》。采集日期为 2026-11-08，尚未联网复核。A/B 可注明来源引用，C 级只能作为线索；产品认证与法规适用性仍需核实。</Notice><div className="intel-toolbar"><select aria-label="情报分类" value={category} onChange={e=>setCategory(e.target.value)}>{[['all','全部条目'],['DEM','需求与区域'],['BUY','买家关注点'],['COMP','竞品'],['PRC','价格'],['REG','法规税费'],['CH','渠道语言'],['TRD','进口交付'],['H','策略假设'],['G','数据缺口']].map(([id,l])=><option value={id} key={id}>{l}</option>)}</select><label className="search"><Search size={16}/><input value={query} placeholder="搜索市场情报" onChange={e=>setQuery(e.target.value)}/></label></div><div className="intel-list">{entries.map(e=><Panel key={e.id}><div className="intel-head"><strong>{e.id}</strong><Tag tone={e.confidence?.startsWith('C')?'amber':''}>{e.confidence} 级</Tag><small>有效期至 {e.expires_at}</small></div><p>{e.text}</p><div className="intel-source"><FileText size={14}/>{e.source}</div>{e.urls?.map(u=><a className="text-link" href={u} target="_blank" rel="noreferrer" key={u}>查看原始来源 <ExternalLink size={13}/></a>)}<p className="intel-implication">策略参考：{e.implication}</p></Panel>)}</div></>}
export function Channels({state,go,mutate,notify,busy,guard}){
 const [modal,setModal]=useState(null);const types=[{id:'whatsapp',name:'WhatsApp Business',description:'接收买家的询盘，在 24 小时客服窗口内回复。',logo:'W',class:'whatsapp',fields:'企业号码 ID',restrictions:'仅支持官方 Business Platform / Cloud API。窗口外普通消息会被拦截，不能使用个人号自动化。'},{id:'facebook',name:'Facebook 主页',description:'把主页私信接入团队，让每一条询盘都有跟进。',logo:'f',class:'facebook',fields:'Facebook 主页 ID',restrictions:'使用 Messenger Platform。开发模式仅限应用角色用户；向所有客户开放需完成 Meta 应用审核。'},{id:'email',name:'询盘邮箱',description:'接收企业邮箱询盘，在原始邮件线程里回复。',logo:'@',class:'email',fields:'邮箱',restrictions:'通过 Resend 官方 API 接入。需验证发送域名与接收邮件路由、SPF/DKIM；只回复已有线程，不群发。'}];
 const health={connected:'已连接',authorized:'已授权，等待首条消息',reauthorize:'需要重新授权',disconnected:'已断开'};
 return <><SectionTitle title="让客户在熟悉的地方，找到你" description="买家通过自己的渠道联系，团队在统一收件箱接手。只回复主动联系的客户。"><Button variant="outline" icon={BriefcaseBusiness} onClick={()=>go('business')}>查看收件箱</Button></SectionTitle><div className="channel-cards">{types.map(t=>{const c=state.channels.find(c=>c.channel===t.id);return <Panel className="channel-card" key={t.id}><div className="channel-card-head"><span className={'channel-logo '+t.class}>{t.logo}</span><Tag tone={c?.health==='connected'?'':c?.health==='reauthorize'?'red':'neutral'}>{health[c?.health]||'未连接'}</Tag></div><h2>{t.name}</h2><p>{t.description}</p><dl className="details-list"><dt>最近消息</dt><dd>{fmt(c?.last_webhook_at)}</dd><dt>账号</dt><dd>{c?.account_id||'尚未绑定'}</dd>{c?.channel==='email'?<><dt>回调路径</dt><dd className='break-all'>{'/webhooks/email?account='+c.id}</dd></>:null}</dl><div className="channel-card-actions"><Button variant={c?.health==='connected'?'outline':''} onClick={()=>guard(()=>setModal(t))}>{c?.health==='connected'?'重新授权':'连接'+t.name}</Button>{c&&c.health!=='disconnected'?<button className="text-link danger" onClick={()=>catchIt(mutate('/channels/disconnect',{id:c.id},'渠道已断开，授权令牌已删除'))}>断开</button>:null}</div><small>{t.restrictions}</small></Panel>})}</div><div className="two-col"><Panel><SectionTitle title="接入前，准备好这些"/>{[['企业自己的业务账号','Facebook 主页需已发布；WhatsApp 使用企业或 Meta 测试号码。'],['经过审核的应用与权限','开发模式先使用已登记测试账号，正式开放前完成平台审核。'],['稳定的消息回调','收到消息后验签、去重，再交给团队。授权成功不等于已收到真实消息。']].map(([t,d],i)=><div className="setup-step" key={t}><span>{i+1}</span><div><strong>{t}</strong><p>{d}</p></div></div>)}</Panel><Panel className="teal-panel"><ShieldCheck size={29}/><h2>连接渠道，<br/>不等于放开所有权限。</h2><div className="rule"><Check size={15}/><span>首次回复只说已确认的事实</span></div><div className="rule"><Check size={15}/><span>报价仍需双钥匙和你的批准</span></div><div className="rule"><Check size={15}/><span>退订后，网关拦截所有后续消息</span></div><div className="rule"><Check size={15}/><span>发送结果不确定时先核对，避免重复打扰</span></div></Panel></div>{modal?<Modal title={'连接 '+modal.name} description="凭据只发送到服务端加密保存，AI 不接触令牌。" onClose={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(e.currentTarget));b.channel=modal.id;try{const out=await mutate('/channels/connect',b,'授权已验证，请配置公共回调并发送一条测试消息');if(out.callback_path)notify('请使用公共网关回调地址：'+out.callback_path);setModal(null)}catch{}}}>{modal.id!=='email'?<Notice tone={!state.capabilities.meta?'warning':''}>{state.capabilities.meta?'平台已准备好接收官方渠道授权。':'平台管理员尚未完成 Meta 应用配置，请完成配置后再连接。'}</Notice>:<Notice>需先在 Resend 验证发送域名、设置接收路由并创建 email.received Webhook。连接后显示唯一回调路径。</Notice>}<Field label={modal.fields}><input name="account_id" type={modal.id==='email'?'email':'text'} pattern={modal.id==='email'?undefined:'[0-9]{5,30}'} required autoComplete="off"/></Field><Field label={modal.id==='email'?'Resend API Key':'官方访问令牌'} hint="请在此安全表单输入，不要在聊天中发送密钥。"><input name="token" type="password" autoComplete="new-password" required/></Field>{modal.id==='email'?<Field label="Resend Webhook 签名密钥"><input name="webhook_secret" type="password" autoComplete="new-password" placeholder="whsec_…" required/></Field>:null}<Field label="Webhook 回调路径"><input readOnly value={modal.id==='email'?(state.channels.find(c=>c.channel==='email')?'/webhooks/email?account='+state.channels.find(c=>c.channel==='email').id:'连接成功后生成专属回调路径'):'/webhooks/meta'}/></Field><p className="muted">当前主站为私有访问，回调须使用单独部署的公共渠道网关域名。授权后以收到首条真实消息为准。</p><Button loading={busy} type="submit" icon={LockKeyhole}>验证并安全连接</Button></form></Modal>:null}</>;
}
export function Account({state,go,mutate,notify,busy,guard}){
 const [selected,setSelected]=useState('trial'),[method,setMethod]=useState('wechat'),[modal,setModal]=useState(null);const plans=state.plans||{trial:{name:'试用版',fen:9900,days:14,inquiries:30,posts:6},monthly:{name:'月付版',fen:39900,days:30,inquiries:150,posts:12},annual:{name:'年付版',fen:399000,days:365,inquiries:150,posts:12}};const sub=state.subscription;
 return <><SectionTitle title="你的工厂，你的 AI 团队" description="全部功能已开放使用；订阅套餐可选，用于提升询盘与内容配额。"><a className="text-link" href="/signout-with-chatgpt?return_to=%2F" target="_top"><LogOut size={15}/>退出登录</a></SectionTitle><Panel className="account-summary"><Avatar large>{state.factory?.factory?.slice(0,1)||'你'}</Avatar><div><h2>{state.factory?.factory||'建立你的工厂工作区'}</h2><p>{state.factory?.category||'注册后即可免费上传资料、制定出海战略'}</p><small>{state.user?.email||'使用 ChatGPT 账户登录，建立独立工作区'}</small></div><div className="subscription-state"><Tag tone={state.entitled?'':'neutral'}>{state.entitled?plans[sub?.plan]?.name||'团队使用中':sub?'订阅已到期':'免费工作区'}</Tag><small>{state.entitled?`到期时间：${fmt(sub.expires_at)}`:'7 位同事已全部开放使用'}</small>{!state.registered?<Button variant="small" onClick={()=>guard()}>建立免费工作区</Button>:null}</div></Panel><SectionTitle title="选择适合你的节奏" description="所有套餐均包含 7 位 Agent，订阅只收软件服务费，不经手买家货款。"/><div className="pricing-grid">{Object.entries(plans).map(([id,p])=><button key={id} className={'pricing-card '+(selected===id?'selected':'')} onClick={()=>setSelected(id)}><div className="plan-name"><strong>{p.name}</strong><span className="choice-check">{selected===id?<Check size={15}/>:null}</span></div><div className="plan-price">¥{p.fen/100}<small> / {id==='trial'?'14 天':id==='monthly'?'月':'年'}</small></div><p>{id==='trial'?'用真实询盘，试一次完整协作':id==='monthly'?'按月续费，持续运转':'按年安排你的出海业务'}</p><div className="plan-benefits"><span><Check size={15}/>7 位 AI 同事协作</span><span><Check size={15}/>{p.inquiries} 条询盘 / {id==='trial'?'14 天':'月'}</span><span><Check size={15}/>{p.posts} 篇内容 / {id==='trial'?'14 天':'月'}</span><span><Check size={15}/>审批、日志与经营简报</span></div>{id==='trial'?<small>试用每个账户限购一次</small>:id==='annual'?<small>折合 ¥332.50 / 月</small>:<small>到期提醒，自主决定是否续费</small>}</button>)}</div><Panel className="checkout-panel"><div><h3>准备让完整团队上岗？</h3><p>请先完成事实确认与战略批准，再选择支付方式。</p><div className="payment-methods"><button className={method==='wechat'?'chosen':''} onClick={()=>setMethod('wechat')}><span className="pay-icon wechat">微</span>微信支付{method==='wechat'?<Check size={15}/>:null}</button><button className={method==='alipay'?'chosen':''} onClick={()=>setMethod('alipay')}><span className="pay-icon alipay">支</span>支付宝{method==='alipay'?<Check size={15}/>:null}</button></div></div><div className="checkout-action"><strong>¥{plans[selected].fen/100}<small>{selected==='trial'?' / 14 天':selected==='monthly'?' / 月':' / 年'}</small></strong><Button icon={ArrowRight} loading={busy} onClick={()=>{if(!guard())return;catchIt(mutate('/checkout',{plan:selected,method}).then(out=>setModal({type:'pay',order:out})))}}>开通{plans[selected].name}</Button><small>{state.capabilities.payment?'由官方支付渠道收款，平台验签后生效':'收款通道尚未开通，请联系平台管理员'}</small></div></Panel><div className="two-col"><Panel><SectionTitle title="账单与支付记录"/>{state.payments?.length?<div className="table-wrap"><table><thead><tr><th>套餐</th><th>金额</th><th>状态</th><th></th></tr></thead><tbody>{state.payments.map(p=><tr key={p.id}><td>{plans[p.plan]?.name}<small className="block-note">{fmt(p.created_at)}</small></td><td>{money(p.amount_fen,'CNY')}</td><td><Status status={p.status}/></td><td>{p.status==='paid'?<button className="text-link" onClick={()=>setModal({type:'invoice',payment:p})}>申请发票</button>:p.status==='pending'&&p.checkout_url?<a href={p.checkout_url} target="_blank" rel="noreferrer" className="text-link">继续支付</a>:null}</td></tr>)}</tbody></table></div>:<Empty icon={Receipt} title="还没有支付记录" description="开通后，套餐、支付状态和发票申请会集中保存在这里。"/>}</Panel><Panel><SectionTitle title="数据与导出"/><p className="muted">资料与历史记录始终可查看和导出。</p><a href="/api/export" className="text-link"><Download size={15}/>导出我的业务与操作记录</a></Panel></div>{modal?.type==='pay'?<Modal title="完成支付后，团队正式上岗" description="请在支付渠道完成付款。付款成功状态以平台核验回调为准。" onClose={()=>setModal(null)}><div className="payment-confirm"><Wallet size={40}/><h2>{money(modal.order.amount_fen,'CNY')}</h2><small>订单号 {modal.order.id}</small><a className="btn" href={modal.order.checkout_url} target="_blank" rel="noreferrer">打开安全收银台 <ExternalLink size={16}/></a><p>支付完成后，本页面会自动刷新权益状态。</p></div></Modal>:modal?.type==='invoice'?<Modal title="申请发票" description="已支付订阅可申请开票，由平台运营核实后处理。" onClose={()=>setModal(null)}><form onSubmit={async e=>{e.preventDefault();try{await mutate('/invoice',{...Object.fromEntries(new FormData(e.currentTarget)),payment_id:modal.payment.id},'开票申请已提交');setModal(null)}catch{}}}><Field label="发票抬头"><input name="title" required/></Field><Field label="纳税人识别号"><input name="tax_id" required/></Field><Field label="接收邮箱"><input name="email" type="email" required/></Field><Button type="submit" loading={busy}>提交开票申请</Button></form></Modal>:null}</>;
}
